<?php require __DIR__ . '/layout.php'; $usuari = $biblioteca->cercarUsuari((int)($_GET['id'] ?? 0)); ?>
<h1><?= $usuari ? htmlspecialchars($usuari->nom) : 'Usuari no trobat' ?></h1><?php if ($usuari): ?><p><?= htmlspecialchars((string)$usuari) ?></p><p><a href="index.php?page=usuari&id=<?= $usuari->id ?>&action=prestecs">Veure historial de préstecs</a></p><ul><?php foreach ($usuari->getMaterialsPrestats() as $m): ?><li><?= htmlspecialchars($m->getTitol()) ?></li><?php endforeach; ?></ul><?php if (($_GET['action'] ?? '') === 'prestecs'): ?><h2>Historial de préstecs</h2><ul><?php foreach ($biblioteca->llistarPrestecsUsuari($usuari->id) as $p): ?><li><?= htmlspecialchars($p->getMaterial()->getTitol()) ?> - <?= $p->estaActiu() ? 'Actiu' : 'Retornat' ?></li><?php endforeach; ?></ul><?php endif; ?><?php endif; ?></main></body></html>
